  authoritativeCapabilities: readonly string[];
  clientClaimedCapabilities: unknown;
}): readonly string[] {
  if (input.clientClaimedCapabilities === undefined || input.clientClaimedCapabilities === null) {
    return input.authoritativeCapabilities;
